        const email = prompt('Enter your email to start your free trial:');
        if (email) {
          alert(`Thanks! We sent a sign-up link to ${email}.`);
        }
      });
    }

    renderTabs();
    renderCourses('Featured');
    renderTeachers();
    renderTestimonials();
    renderFaq();
    wireHeroActions();
  </script>
