      faqs.forEach((item, idx) => {
        const node = document.createElement('article');
        node.className = 'faq-item' + (idx === 0 ? ' active' : '');
        node.innerHTML = `
          <button class="faq-q" aria-expanded="${idx === 0 ? 'true' : 'false'}">
            <span>${item.q}</span>
            <span>${idx === 0 ? '−' : '+'}</span>
          </button>
          <div class="faq-a"><p>${item.a}</p></div>
        `;
        const btn = node.querySelector('.faq-q');
        btn.addEventListener('click', () => {
          const isOpen = node.classList.contains('active');
          document.querySelectorAll('.faq-item').forEach(f => {
            f.classList.remove('active');
            f.querySelector('.faq-q').setAttribute('aria-expanded', 'false');
            f.querySelector('.faq-q span:last-child').textContent = '+';
          });
          if (!isOpen) {
            node.classList.add('active');
            btn.setAttribute('aria-expanded', 'true');
            btn.querySelector('span:last-child').textContent = '−';
          }
        });
